<?php
require_once __DIR__ . '/../config/config.php';require_once __DIR__ . '/../includes/session.php';require_once __DIR__ . '/../includes/auth.php';require_login();require_module_access($conn,'maternity','view');$canCreate=can_module_action($conn,'maternity','create');
$r=$conn->query("SELECT a.id,a.patient_id,a.admission_id,a.visit_id,a.admission_date,a.ward,a.status,a.note,p.full_name,p.patient_number,ca.ward_name,ca.bed_number,ca.status AS clinical_status FROM maternity_admissions a JOIN patients p ON p.id=a.patient_id LEFT JOIN admissions ca ON ca.id=a.admission_id ORDER BY a.id DESC LIMIT 200");
include __DIR__ . '/../includes/header.php';include __DIR__ . '/../includes/sidebar.php';?>
<div class="main-content"><div class="container-fluid pt-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="h4 mb-1 text-gray-800"><i class="fas fa-procedures text-primary mr-2"></i>Maternity Admissions</h2><p class="text-muted mb-0">Track maternal care while using the shared clinical inpatient admission and visit.</p></div><?php if($canCreate):?><a href="new_admission.php" class="btn btn-primary"><i class="fas fa-plus mr-1"></i>New Admission</a><?php endif;?></div><div class="card shadow-sm"><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Patient</th><th>Admission Date</th><th>Maternity Area</th><th>Clinical Bed</th><th>Status</th><th>Notes</th><th>Action</th></tr></thead><tbody><?php if($r&&$r->num_rows):while($a=$r->fetch_assoc()):?><tr><td><strong><?=htmlspecialchars($a['full_name'])?></strong><br><small><?=htmlspecialchars($a['patient_number'])?></small></td><td><?=htmlspecialchars($a['admission_date'])?></td><td><?=htmlspecialchars($a['ward'])?></td><td><?=!empty($a['bed_number'])?'Bed '.(int)$a['bed_number']:'—'?></td><td><span class="badge badge-<?=strtolower($a['status']??'')==='admitted'?'success':'secondary'?>"><?=htmlspecialchars($a['status']??'')?></span></td><td><?=htmlspecialchars($a['note']??'')?></td><td><?php if(($a['clinical_status']??'')==='Admitted' && !empty($a['admission_id'])):?><a class="btn btn-sm btn-outline-danger" href="../clinical/discharge_patient.php?id=<?=((int)$a['admission_id'])?>">Discharge</a><?php elseif(($a['status']??'')==='Discharged'):?><span class="text-muted small">Discharged</span><?php else:?>—<?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="7" class="text-center text-muted py-5">No maternity admissions found.</td></tr><?php endif;?></tbody></table></div></div></div></div></div><?php include __DIR__ . '/../includes/footer.php'; ?>